                  disabled: true,
                  componentsBefore: [<Placeholder />],
                  componentsAfter: [<Badge mode="neutral" text="25" />],
                  description: 'With tooltip',
                  tooltip: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit',
